// src/contexts/AuthContext.tsx
import React, { createContext, useContext, useReducer, useEffect } from 'react';
import type { AuthState, AuthContextType, LoginCredentials, RegisterCredentials } from '../types/auth.types';
import * as authApi from '../services/auth.service';

const initialState: AuthState = {
  user: null,
  token: localStorage.getItem('token'),
  isAuthenticated: !!localStorage.getItem('token'),
  isLoading: false,
  error: null,
};

// ... (keep your existing action types and reducer)

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [state, dispatch] = useReducer(authReducer, initialState);

  useEffect(() => {
    const initializeAuth = async () => {
      const token = localStorage.getItem('token');
      if (token) {
        try {
          dispatch({ type: 'AUTH_START' });
          const user = await authApi.getCurrentUser();
          dispatch({ type: 'AUTH_SUCCESS', payload: { user, token } });
        } catch (error) {
          console.error('Error initializing auth:', error);
          localStorage.removeItem('token');
          dispatch({ type: 'AUTH_ERROR', payload: 'Session expired' });
        }
      }
    };

    initializeAuth();
  }, []);

  const login = async (credentials: LoginCredentials) => {
    try {
      console.log('AuthContext: Starting login process');
      dispatch({ type: 'AUTH_START' });

      const { user, token } = await authApi.login(credentials);
      console.log('AuthContext: Login successful', { user, token });

      if (!token) {
        throw new Error('No token received from server');
      }

      localStorage.setItem('token', token);
      dispatch({ type: 'AUTH_SUCCESS', payload: { user, token } });

      return { user, token }; // Return the response for the component to use
    } catch (error) {
      console.error('AuthContext: Login error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Failed to login';
      dispatch({ type: 'AUTH_ERROR', payload: errorMessage });
      throw error;
    }
  };

  // ... (keep your existing register and logout functions)

  const value = {
    ...state,
    login,
    register,
    logout,
    clearError,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};
